module parity_8bit (
    input [7:0] in,
    output out
);
    wire xor_10 = in[1] ^ in[0];
    wire xor_32 = in[3] ^ in[2];
    wire xor_54 = in[5] ^ in[4];
    wire xor_76 = in[7] ^ in[6];
    wire xor_l = xor_10 ^ xor_32;
    wire xor_r = xor_54 ^ xor_76;
    assign out = xor_l ^ xor_r;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire sel0_n = ~sel[0];
    wire sel1_n = ~sel[1];

    wire a0 = in[0] & sel0_n & sel1_n;
    wire a1 = in[1] & sel[0] & sel1_n;
    wire a2 = in[2] & sel0_n & sel[1];
    wire a3 = in[3] & sel[0] & sel[1];

    assign out = a0 | a1 | a2 | a3;
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] x;
    assign x = a ^ b;
    wire w0, w1;
    assign w0 = ~(x[0] | x[1]);
    assign w1 = ~(x[2] | x[3]);
    assign equal = w0 & w1;
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out[0] = ~(~in[1] & ~in[0]);
    assign out[1] = ~(~in[1] & in[0]);
    assign out[2] = ~(in[1] & ~in[0]);
    assign out[3] = ~(in[1] & in[0]);
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    wire and1_out = in[2] & in[3];
    wire not_and1 = ~and1_out;
    wire and2_out = not_and1 & in[1];

    assign code[0] = not_and1;
    assign code[1] = and2_out;
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg q0, q1;
    wire d0, d1;
    wire nq0, nq1;

    assign nq0 = ~q0;
    assign nq1 = ~q1;

    // First FF (left): D = ~Q0, R = reset
    assign d0 = nq0;
    // Second FF (right): D = Q0 ^ Q1, R = reset
    assign d1 = q0 ^ q1;

    always @(posedge clk) begin
        if (reset) begin
            q0 <= 0;
            q1 <= 0;
        end else begin
            q0 <= d0;
            q1 <= d1;
        end
    end

    // state[1] = mux: sel=q1, 0->q0, 1->~q0  => q1 ? ~q0 : q0 = q0 ^ q1
    // state[0] = q0 & q1
    assign state[1] = q0 ^ q1;
    assign state[0] = q0 & q1;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [1:0] state;

    wire q1 = state[1];
    wire q0 = state[0];

    // Next state logic
    wire n1 = q1 ^ q0;
    wire n0_nand1 = ~(q1 & q0);
    wire n0_nand2 = ~(n0_nand1 & q1);
    wire n0_inv = ~(q0 & clk);
    wire n0 = ~(n0_nand2 | n0_inv);

    // Flip-flops with reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            state[1] <= q1 ^ q0;
            state[0] <= ~q0;
        end
    end

    // Output logic
    wire and1 = q1 & ~q0;
    wire and2 = ~q1 & q0;

    assign light[2] = ~(q1 | q0);      // green: state 00
    assign light[1] = and2;              // yellow: state 01
    assign light[0] = q1;               // red: state 10, 11

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    wire Q0, Q1;
    reg D0, D1;

    // Two DFFs with async reset
    reg ff0, ff1;

    assign Q0 = ff0;
    assign Q1 = ff1;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ff0 <= 0;
            ff1 <= 0;
        end else begin
            ff0 <= D0;
            ff1 <= D1;
        end
    end

    // Next state logic derived from the circuit diagram
    // D0 is input to top FF, D1 is input to bottom FF

    wire n_Q0 = ~Q0;
    wire n_Q1 = ~Q1;
    wire n_down = ~down_request;
    wire n_up = ~up_request;

    // Analyzing the diagram for D0 (top FF):
    // D0 = (down_request & ~Q1) | (~Q0 & ~Q1 & down_request) | (Q0 & ~down_request & ~up_request)
    // Simplifying based on typical elevator FSM and diagram structure:

    wire and1 = n_Q0 & n_Q1;
    wire and2 = Q0 & Q1;

    // D0: top flip-flop input
    // From diagram: involves down_request, Q0, Q1 and their complements
    wire t1 = and1 & down_request;
    wire t2 = Q0 & n_Q1 & (~down_request & ~up_request);
    wire t3 = and2 & down_request;
    always @(*) begin
        D0 = t1 | t2 | t3;
    end

    // D1: bottom flip-flop input
    wire t4 = and1 & up_request;
    wire t5 = n_Q0 & Q1 & (~down_request & ~up_request);
    wire t6 = and2 & up_request;
    always @(*) begin
        D1 = t4 | t5 | t6;
    end

    assign state[0] = Q0;
    assign state[1] = Q1;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    wire Q0, Q1; // Q1 = state[1] (top FF), Q0 = state[0] (bottom FF)
    wire D1, E1, D0, E0;

    // Bottom FF (state[0] / Q0) - S_DFFE_PP0P_
    // Top FF (state[1] / Q1) - S_DFFE_PP0P_

    // Analyzing the circuit:
    // The bottom FF has: C=clk, R=reset
    // The top FF has: C=clk, R=reset

    // From the diagram, tracing the logic:

    // For bottom FF (Q0):
    // E0 = item_selected
    // D0 = coin_inserted & ~Q1

    // For top FF (Q1):
    // The NAND/AND logic at top:
    // E1 = ~(Q1 & ~Q0) = ~Q1 | Q0
    // D1 = ~(~Q0 & ~coin_inserted) = Q0 | coin_inserted

    // state[0] = Q1 (top FF output)
    // state[1] = AND of Q0 and Q1 based on output logic

    // Let me re-examine more carefully.
    // state is 2-bit output with a mux-like structure at right

    // The output shows state[0] = Q1 (top FF), state[1] = AND gate of Q0, Q1 and something

    // Let me use a simpler behavioral approach matching the S_DFFE_PP0P_ cells
    // S_DFFE_PP0P_ = DFF with positive clk, positive enable, negative reset (async reset to 0)

    reg ff0, ff1;

    // Bottom FF (Q0 = ff0)
    wire e0 = item_selected;
    wire nand_coin_q0 = ~(coin_inserted & ff0);
    wire and_coin_nq1 = coin_inserted & ~ff1;
    wire d0 = and_coin_nq1;

    // Top FF (Q1 = ff1)  
    wire nand_q1_nq0 = ~(ff1 & ~ff0);
    wire e1 = nand_q1_nq0;
    wire nand_mid = ~(~ff0 & ~coin_inserted);
    wire d1 = nand_mid;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ff0 <= 0;
        end else if (e0) begin
            ff0 <= d0;
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ff1 <= 0;
        end else if (e1) begin
            ff1 <= d1;
        end
    end

    // Output logic
    assign state[0] = ff1;
    assign state[1] = ff0 & ff1;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    reg signed [15:0] result;
    integer i;

    always @(*) begin
        if (in_1 == 0) begin
            result = 16'sd1;
        end else if (in_1 < 0) begin
            result = 16'sd0;
        end else begin
            result = {{8{in_0[7]}}, in_0};
            for (i = 1; i < 15; i = i + 1) begin
                if (i < in_1)
                    result = result * {{8{in_0[7]}}, in_0};
            end
        end
    end

    assign out = result;
endmodule

