endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010;

    wire [3:0] left = data_in[7:4];
    wire [3:0] right = data_in[3:0];

    wire [3:0] f_out;
    assign f_out[0] = right[0] ^ KEY[0];
    assign f_out[1] = right[1] ^ KEY[1];
    assign f_out[2] = right[2] ^ KEY[2];
    assign f_out[3] = right[3] ^ KEY[3];

    wire [3:0] new_right;
    assign new_right[0] = left[0] ^ f_out[0];
    assign new_right[1] = left[1] ^ f_out[1];
    assign new_right[2] = left[2] ^ f_out[2];
    assign new_right[3] = left[3] ^ f_out[3];

    assign data_out = {right, new_right};

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg q;
    always @(posedge clk) begin
        if (rst)
            q <= 0;
        else
            q <= ~q;
    end
    assign clk_out = ~q;
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
  wire [3:0] x;
  assign x = a ^ b;

  wire eq3 = ~x[3];
  wire eq2 = ~x[2];
  wire eq1 = ~x[1];
  wire eq0 = ~x[0];

  wire gt3 = a[3] & ~b[3];
  wire gt2 = eq3 & a[2] & ~b[2];
  wire gt1 = eq3 & eq2 & a[1] & ~b[1];
  wire gt0 = eq3 & eq2 & eq1 & a[0] & ~b[0];

  wire lt3 = ~a[3] & b[3];
  wire lt2 = eq3 & ~a[2] & b[2];
  wire lt1 = eq3 & eq2 & ~a[1] & b[1];
  wire lt0 = eq3 & eq2 & eq1 & ~a[0] & b[0];

  assign gt = gt3 | gt2 | gt1 | gt0;
  assign lt = lt3 | lt2 | lt1 | lt0;
  assign eq = ~(gt | lt);
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    wire in1_n = ~in[1];
    wire in0_n = ~in[0];

    assign out[0] = ~(in1_n & in0_n & enable);
    assign out[1] = ~(in1_n & in[0] & enable);
    assign out[2] = ~(in[1] & in0_n & enable);
    assign out[3] = ~(in[1] & in[0] & enable);
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
  assign out[0] = enable & ~in[2] & ~in[1] & ~in[0];
  assign out[1] = enable & ~in[2] & ~in[1] &  in[0];
  assign out[2] = enable & ~in[2] &  in[1] & ~in[0];
  assign out[3] = enable & ~in[2] &  in[1] &  in[0];
  assign out[4] = enable &  in[2] & ~in[1] & ~in[0];
  assign out[5] = enable &  in[2] & ~in[1] &  in[0];
  assign out[6] = enable &  in[2] &  in[1] & ~in[0];
  assign out[7] = enable &  in[2] &  in[1] &  in[0];
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    assign out1 = sel & in;
    assign out0 = ~sel & in;
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);
    assign out1 = in & sel[0];
