module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] binary_count;
    wire [7:0] gray_count;

    always @(posedge clk) begin
        if (rst)
            binary_count <= 8'd0;
        else
            binary_count <= binary_count + 8'd1;
    end

    assign gray_count = binary_count ^ (binary_count >> 1);
    assign count = gray_count;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    reg [3:0] q_reg;
    assign q = q_reg;

    always @(posedge clk) begin
        if (rst) begin
            q_reg <= 4'b0000;
        end else begin
            q_reg[0] <= ~q_reg[3];
            q_reg[1] <= q_reg[0];
            q_reg[2] <= q_reg[1];
            q_reg[3] <= q_reg[2];
        end
    end
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

    reg [7:0] shift_reg;

    wire rst_inv = ~rst;

    always @(posedge clk or negedge rst_inv) begin
        if (!rst_inv) begin
            shift_reg <= 8'b0;
        end else if (load) begin
            shift_reg <= pin;
        end else begin
            shift_reg <= {shift_reg[6:0], 1'b0};
        end
    end

    assign sout = shift_reg[7];

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);

    assign out[1] = in[2] | in[3];
    assign out[0] = in[3] | (in[1] & ~in[2]);
    assign valid = |in;

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    reg [3:0] q_reg;
    assign q = q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_reg <= 4'b0010;
        end else begin
            q_reg <= {q_reg[2:0], q_reg[3]};
        end
    end
endmodule

module sipo_8bit(
