    reg [7:0] shift;
    always @(posedge clk) begin
        if (rst)
            shift <= 8'b0;
        else
            shift <= {shift[6:0], sin};
    end
    assign sout = shift[7];
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
    reg [7:0] cnt;
    assign count = cnt;

    always @(posedge clk or posedge rst) begin
        if (rst)
            cnt <= 8'b0;
        else
