    end
endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] state;

  // Round-robin arbiter FSM
  // state tracks which requester has highest priority (one-hot or idle)

  wire no_grant = ~|r;

  // On reset, go to idle state where device 0 has highest priority
  // This is a fixed-priority arbiter that rotates priority after each grant

  reg [2:0] last;

  always @(posedge clk) begin
    if (~resetn)
      last <= 3'b000;
    else begin
      if (g[0]) last <= 3'b001;
      else if (g[1]) last <= 3'b010;
      else if (g[2]) last <= 3'b100;
    end
  end

  // Round-robin grant logic based on last granted
  reg [2:0] g_reg;

  always @(*) begin
    g_reg = 3'b000;
    case (last)
      3'b000: begin // no previous grant, priority 0>1>2
        if (r[0]) g_reg = 3'b001;
        else if (r[1]) g_reg = 3'b010;
        else if (r[2]) g_reg = 3'b100;
      end
      3'b001: begin // last was 0, priority 1>2>0
        if (r[1]) g_reg = 3'b010;
        else if (r[2]) g_reg = 3'b100;
        else if (r[0]) g_reg = 3'b001;
      end
      3'b010: begin // last was 1, priority 2>0>1
        if (r[2]) g_reg = 3'b100;
        else if (r[0]) g_reg = 3'b001;
        else if (r[1]) g_reg = 3'b010;
      end
      3'b100: begin // last was 2, priority 0>1>2
        if (r[0]) g_reg = 3'b001;
        else if (r[1]) g_reg = 3'b010;
        else if (r[2]) g_reg = 3'b100;
      end
      default: begin
        if (r[0]) g_reg = 3'b001;
        else if (r[1]) g_reg = 3'b010;
        else if (r[2]) g_reg = 3'b100;
      end
    endcase
  end

  assign g = g_reg;

endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);
  wire mux1 = L ? R : (E ? w : Q);
  wire en = L | E;

  always @(posedge clk) begin
    if (en)
      Q <= mux1;
  end
endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);
  assign out_assign = a ^ b;
  always @(*) out_alwaysblock = a ^ b;
endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);
  assign out_assign = a ^ b;
  always @(*) out_always_comb = a ^ b;
  always @(posedge clk) out_always_ff <= a ^ b;
endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);
  wire sel = sel_b1 & sel_b2;
  assign out_assign = sel ? b : a;
  always @(*) out_always = sel ? b : a;
endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
