module TopModule (
  input clk,
  input in,
  input reset,
  output done
);
  // FSM for serial protocol: idle, start bit, 8 data bits, stop bit
  reg [3:0] state;

  localparam IDLE = 4'd0;
  localparam BIT0 = 4'd1;
  localparam BIT1 = 4'd2;
  localparam BIT2 = 4'd3;
  localparam BIT3 = 4'd4;
  localparam BIT4 = 4'd5;
  localparam BIT5 = 4'd6;
  localparam BIT6 = 4'd7;
  localparam BIT7 = 4'd8;
  localparam STOP = 4'd9;
  localparam WAIT = 4'd10;

  reg done_reg;
  assign done = done_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      done_reg <= 0;
    end else begin
      done_reg <= 0;
      case (state)
        IDLE: begin
          if (~in)
            state <= BIT0;
        end
        BIT0: state <= BIT1;
        BIT1: state <= BIT2;
        BIT2: state <= BIT3;
        BIT3: state <= BIT4;
        BIT4: state <= BIT5;
        BIT5: state <= BIT6;
        BIT6: state <= BIT7;
        BIT7: state <= STOP;
        STOP: begin
          if (in) begin
            done_reg <= 1;
            state <= IDLE;
          end else begin
            state <= WAIT;
          end
        end
        WAIT: begin
          if (in)
            state <= IDLE;
        end
        default: state <= IDLE;
      endcase
    end
  end
endmodule

