module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State encoding: 2 bits for direction (left/right) and falling
  // From the diagram, there are flip-flops with async reset
  // This appears to be a Lemmings walker: walks left/right, falls when no ground

  reg [1:0] state;
  // States: 00 = walk_left, 01 = walk_right, 10 = fall_left, 11 = fall_right

  localparam WL = 2'b00, WR = 2'b01, FL = 2'b10, FR = 2'b11;

  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= WL;
    else begin
      case (state)
        WL: begin
          if (!ground) state <= FL;
          else if (bump_left) state <= WR;
        end
        WR: begin
          if (!ground) state <= FR;
          else if (bump_right) state <= WL;
        end
        FL: begin
          if (ground) state <= WL;
        end
        FR: begin
          if (ground) state <= WR;
        end
      endcase
    end
  end

  assign walk_left  = (state == WL);
  assign walk_right = (state == WR);
  assign aaah       = (state == FL) || (state == FR);

endmodule

