  // Bottom AND: x[2] & ~x[0]
  assign n2 = ~(x[2] & x[0]);

  // NOR of the two NAND outputs
  assign n3 = ~(n1 | n2);

  // Also: ~x[1] & ~x[3] -> NAND, then AND with ~x[2] & x[0]
  // Let me re-read the diagram more carefully.

  // x[1], x[3] feed top NAND -> n1
  // x[2], x[0] feed bottom NAND -> n2
  // ~n1 and ~n2 ... 

  // Let me just trace it:
  // Top path: x[1] & x[3] -> NAND -> invert -> AND with something
  // Bottom path: x[2] & x[0] -> NAND -> invert -> ...

  // Actually, looking more carefully:
  // Gate1 (NAND): inputs x[1], ~x[3] -> output n1
  // Gate2 (NAND): inputs x[2], x[0] -> output n2  
  // Gate3 (NOR): inputs n1, n2 -> but with bubbles... 

  // Let me try a simpler interpretation:
  // f = (~x[3] & x[1]) | (x[2] & ~x[0])
  // No wait...

  // The decoder-like block splits x into x[1], x[3], x[2], x[0]
  // Top NAND has inputs: ~x[3], x[1] (x[3] has bubble) -> NAND(~x[3], x[1])
  // Then inverted (bubble on output going to NOR) 
  // Bottom NAND: x[2], ~x[0] (x[0] has bubble) -> NAND(x[2], ~x[0])
