module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  reg [2:0] state;

  localparam SA = 3'd0; // reset/idle
  localparam SB = 3'd1; // after reset, f=1 for one cycle
  localparam SC = 3'd2; // monitoring x, waiting for 1
  localparam SD = 3'd3; // got x=1, waiting for 0
  localparam SE = 3'd4; // got x=1,0, waiting for 1
  localparam SF = 3'd5; // detected pattern 101, g=1, check y
  localparam SG = 3'd6; // g=1 permanently
  localparam SH = 3'd7; // g=0 permanently

  always @(posedge clk) begin
    if (!resetn) begin
      state <= SA;
    end else begin
      case (state)
        SA: state <= SB;
        SB: state <= SC;
        SC: state <= x ? SD : SC;
        SD: state <= x ? SD : SE;
        SE: state <= x ? SF : SC;
        SF: begin
          if (y) state <= SG;
          else state <= SH;
        end
        SG: state <= SG;
        SH: state <= SH;
        default: state <= SA;
      endcase
    end
  end

  assign f = (state == SB);
  assign g = (state == SF) || (state == SG);

endmodule

