module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [8:0] c;
    assign c[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign sum[i] = a[i] ^ b[i] ^ c[i];
            assign c[i+1] = (a[i] & b[i]) | (a[i] & c[i]) | (b[i] & c[i]);
        end
    endgenerate

    assign cout = c[8];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [4:0] binary_sum;
    wire correction;
    wire [3:0] corrected_sum;

    // First, perform binary addition
    assign binary_sum = A + B + Cin;

    // Correction needed if sum > 9
    assign correction = (binary_sum > 5'd9) ? 1'b1 : 1'b0;

    // If correction needed, add 6 and set carry
    assign Cout = correction;
    assign corrected_sum = correction ? (binary_sum[3:0] + 4'd6) : binary_sum[3:0];
    assign Sum = corrected_sum;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire eq2 = ~(A[2] ^ B[2]);
    wire eq1 = ~(A[1] ^ B[1]);
    wire eq0 = ~(A[0] ^ B[0]);

    wire gt2 = A[2] & ~B[2];
    wire gt1 = eq2 & A[1] & ~B[1];
    wire gt0 = eq2 & eq1 & A[0] & ~B[0];

    wire lt2 = ~A[2] & B[2];
    wire lt1 = eq2 & ~A[1] & B[1];
    wire lt0 = eq2 & eq1 & ~A[0] & B[0];

    assign A_greater = ~(~(gt2 | gt1 | gt0));
    assign A_less = ~(~(lt2 | lt1 | lt0));
    assign A_equal = ~(~(eq2 & eq1 & eq0));

endmodule

module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [3:0] x;
    assign x[3] = ~(A[3] ^ B[3]);
    assign x[2] = ~(A[2] ^ B[2]);
    assign x[1] = ~(A[1] ^ B[1]);
    assign x[0] = ~(A[0] ^ B[0]);

    assign A_equal = x[3] & x[2] & x[1] & x[0];

    assign A_greater = (A[3] & ~B[3]) |
                       (x[3] & A[2] & ~B[2]) |
                       (x[3] & x[2] & A[1] & ~B[1]) |
                       (x[3] & x[2] & x[1] & A[0] & ~B[0]);

    assign A_less = (~A[3] & B[3]) |
                    (x[3] & ~A[2] & B[2]) |
                    (x[3] & x[2] & ~A[1] & B[1]) |
                    (x[3] & x[2] & x[1] & ~A[0] & B[0]);

endmodule

