    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

    reg [7:0] high_byte;
    reg [7:0] low_byte;

    wire ena_high = fetch[1];
    wire ena_low = fetch[0];

    always @(posedge clk) begin
        if (rst) begin
            high_byte <= 8'b0;
        end else if (ena_high) begin
            high_byte <= data;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            low_byte <= 8'b0;
        end else if (ena_low) begin
            low_byte <= data;
        end
    end

    assign ins = high_byte[7:5];
    assign ad1 = high_byte[4:0];
    assign ad2 = low_byte;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;
  assign feedback = out[1] ^ out[3];

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      out <= 4'b0000;
    end else begin
      out[0] <= out[3];
      out[1] <= out[0];
      out[2] <= feedback;
      out[3] <= out[2];
    end
  end
endmodule

module right_shifter(clk, q, d);

    input clk;
    input d;
    output [7:0] q;

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {d, shift_reg[7:1]};
    end

    assign q = shift_reg;

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// data_en captured in clk_a domain
	reg data_en_a;
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn)
			data_en_a <= 1'b0;
		else
			data_en_a <= data_en;
	end

	// Two-stage synchronizer for enable into clk_b domain
	reg en_sync1, en_sync2;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			en_sync1 <= 1'b0;
			en_sync2 <= 1'b0;
		end else begin
			en_sync1 <= data_en_a;
			en_sync2 <= en_sync1;
		end
	end

	// Data registers in clk_b domain (first stage, reset by brstn)
	reg [3:0] data_sync1;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn)
			data_sync1 <= 4'b0;
		else
			data_sync1 <= data_in;
	end

	// Output registers with enable (en_sync2)
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn)
			dataout <= 4'b0;
		else if (en_sync2)
			dataout <= data_sync1;
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] state;

parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        MATCH <= 0;
    end else begin
        case (state)
            S0: begin
                MATCH <= 0;
                if (IN)
                    state <= S1;
                else
                    state <= S0;
            end
            S1: begin
                MATCH <= 0;
                if (IN)
                    state <= S1;
                else
                    state <= S2;
            end
            S2: begin
                MATCH <= 0;
                if (IN)
                    state <= S3;
                else
                    state <= S0;
            end
            S3: begin
                MATCH <= 0;
                if (IN)
                    state <= S1;
                else
                    state <= S4;
            end
            S4: begin
                MATCH <= 1;
                if (IN)
                    state <= S3;
                else
                    state <= S0;
            end
            default: begin
                state <= S0;
                MATCH <= 0;
            end
        endcase
    end
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [1:0] cnt;
    reg valid_out_reg;
    reg dout_reg;
    reg [3:0] data_reg;

    // 2-bit counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 2'b00;
        else
            cnt <= cnt + 1'b1;
    end

    // Latch input data when counter is 0
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            data_reg <= 4'b0;
        else if (cnt == 2'b00)
            data_reg <= d;
    end

    // Mux to select bit based on counter
    reg mux_out;
    always @(*) begin
        case (cnt)
            2'b00: mux_out = d[0];
            2'b01: mux_out = data_reg[1];
            2'b10: mux_out = data_reg[2];
            2'b11: mux_out = data_reg[3];
        endcase
    end

    // Output register for dout
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dout_reg <= 1'b0;
        else
            dout_reg <= mux_out;
    end

    // Valid out - high when outputting valid data
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            valid_out_reg <= 1'b0;
        else
            valid_out_reg <= 1'b1;
    end

    assign dout = dout_reg;
    assign valid_out = valid_out_reg;

endmodule

