module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    wire clk_inv;
    wire rst;
    wire q0, q1, q2, q3, q4;
    wire d0, d1, d2, d3, d4;

    assign clk_inv = ~clk;
    assign rst = ~rst_n;

    // FF0: S_DFF_PN0_ clocked on clk_inv, stores data_in
    // Bottom-left FF, C=clk_inv, D=data_in, R=rst
    reg ff0;
    always @(posedge clk_inv or posedge rst)
        if (rst) ff0 <= 0;
        else ff0 <= data_in;
    assign q0 = ff0;

    // FF1: S_DFF_PN0_ clocked on clk_inv, D = AND(q0, data_in)
    reg ff1;
    wire d1_w = q0 & data_in;
    always @(posedge clk_inv or posedge rst)
        if (rst) ff1 <= 0;
        else ff1 <= d1_w;
    assign q1 = ff1;

    // FF2: S_DFF_PN0_ top, clocked on clk, D = AND(q1, ~data_in)
    reg ff2;
    wire d2_w = q1 & (~data_in);
    always @(posedge clk or posedge rst)
        if (rst) ff2 <= 0;
        else ff2 <= d2_w;
    assign q2 = ff2;

    // FF3: S_DFF_PN0_ bottom, clocked on clk_inv, D = AND(q2, ~data_in)
    reg ff3;
    wire d3_w = q2 & (~data_in);
    always @(posedge clk_inv or posedge rst)
        if (rst) ff3 <= 0;
        else ff3 <= d3_w;
    assign q3 = ff3;

    // FF4: S_DFF_PN1_ (active-low reset?), clocked on clk
    // D = OR(q2, q3) & data_in — looking at the AND/OR gates feeding it
    // From diagram: there's an OR gate fed by q2 and q3, then AND with something
    // and NAND at top feeds into it
    // Let me re-examine: top-right has AND, NAND gates connecting to FF4
    // FF4 is S_DFF_PN1_ which has inverted output or different reset polarity

    // Top right: AND(q2, data_in) -> fed into NAND with something -> NOT -> D of FF2? 
    // Let me reconsider the topology for detecting sequence 1100

    // Re-analyzing: the circuit detects 1-1-0-0 then 1 (sequence_detected)
    // sequence_detected = AND(q3, data_in, q4_complement_or_similar)

    // FF4: S_DFF_PN1_ clocked on clk, R=rst
    // D = AND( OR(q2,q3), data_in ) based on the middle OR and AND gates
    reg ff4;
    wire or_23 = q2 | q3;
    wire d4_w = or_23 & data_in;
    always @(posedge clk or posedge rst)
        if (rst) ff4 <= 0;
        else ff4 <= d4_w;
